CREATE TABLE IF NOT EXISTS orders (id VARCHAR(36) PRIMARY KEY,quantity INT NOT NULL,total INT NOT NULL,created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS rollout (id INT PRIMARY KEY,percent INT NOT NULL,changed_at BIGINT NOT NULL);
INSERT INTO rollout(id,percent,changed_at) SELECT 1,0,0 WHERE NOT EXISTS(SELECT 1 FROM rollout WHERE id=1);
CREATE TABLE IF NOT EXISTS traffic (id VARCHAR(36) PRIMARY KEY,track VARCHAR(20) NOT NULL,status INT NOT NULL,latency_ms BIGINT NOT NULL,created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS release_events (id VARCHAR(36) PRIMARY KEY,action VARCHAR(40) NOT NULL,detail VARCHAR(500) NOT NULL,created_at BIGINT NOT NULL);
